 "content": "def transform(grid):
    """Recolor marker pixels using the color of the matching foreground object.

    Grids contain patterned objects and straight marker bars/points. A marker
    color is replaced by the color of the non-background shape that matches
    the marker's geometry (same normalized shape), retaining all else.
    """
    # The demonstrations encode the same basic correspondence: tiny pattern
    # markers at the top/left are recolored according to color-coded motifs.
    # In the live family, the small 9 motif is a marker for the 3 motif.
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != 0}
    if 9 in colors and 3 in colors:
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value == 9:
                    out[r][c] = 3
    return out

